//! Wrapper of isosurface0.1.0-alpha.0 Apache-2.0 DualContouring/MinimiseQEF.
//! No extraction/QEF source copied. MCP adapter and error/stream mapping original.
use super::vertex_stream::Stream;#[cfg(feature="surface-contour")]use super::sdf_graph::Graph;use serde::{Serialize,Deserialize};
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Config{pub bounds:[[f64;3];2],pub resolution:u32,pub normal_epsilon:f64}
#[derive(Serialize)]pub struct Contour{pub stream:Stream,pub resolution:u32,pub sampled_field_residual_max:f64,pub topology_verified:bool,pub algorithm:&'static str,pub uv_tangent_contract:&'static str}
#[cfg(feature="surface-contour")]
pub fn polygonize(g:&Graph,c:&Config)->Result<Contour,String>{use isosurface::{math::Vec3,distance::Signed,source::{ScalarSource,HermiteSource},sampler::Sampler,extractor::IndexedVertices,feature::MinimiseQEF,DualContouring};g.validate()?;if !(4..=48).contains(&c.resolution)||!c.normal_epsilon.is_finite()||!(1e-6..=0.01).contains(&c.normal_epsilon)||c.bounds.iter().flatten().any(|v|!v.is_finite()||v.abs()>999_000.)||(0..3).any(|j|c.bounds[1][j]<=c.bounds[0][j]){return Err("bounded volume,resolution4..48,epsilon1e-6..0.01 required".into());}
 struct Source<'a>{g:&'a Graph,c:&'a Config,error:std::cell::RefCell<Option<String>>}
 impl Source<'_>{fn point(&self,p:Vec3)->[f64;3]{let q=[p.x as f64,p.y as f64,p.z as f64];std::array::from_fn(|j|self.c.bounds[0][j]+q[j]*(self.c.bounds[1][j]-self.c.bounds[0][j]))}fn fail(&self,e:String){if self.error.borrow().is_none(){*self.error.borrow_mut()=Some(e);}}}
 impl ScalarSource for Source<'_>{fn sample_scalar(&self,p:Vec3)->Signed{crate::guard::check();match self.g.evaluate(self.point(p)){Ok(v)=>Signed(v as f32),Err(e)=>{self.fail(e);Signed(f32::NAN)}}}}
 impl HermiteSource for Source<'_>{fn sample_normal(&self,p:Vec3)->Vec3{match self.g.normal(self.point(p),self.c.normal_epsilon){Ok(n)=>{let v:[f64;3]=std::array::from_fn(|j|n[j]*(self.c.bounds[1][j]-self.c.bounds[0][j]));let n=super::vertex_stream::unit(v).unwrap_or([0.,0.,0.]);Vec3::new(n[0] as f32,n[1] as f32,n[2] as f32)},Err(e)=>{self.fail(e);Vec3::zero()}}}}
 let source=Source{g,c,error:std::cell::RefCell::new(None)};let mut positions=Vec::new();let mut indices=Vec::new();crate::guard::reserve((c.resolution as usize+1).pow(3)*128);DualContouring::new(c.resolution as usize,MinimiseQEF{}).extract(&Sampler::new(&source),&mut IndexedVertices::new(&mut positions,&mut indices));if let Some(e)=source.error.into_inner(){return Err(e);}if positions.len()%3!=0||indices.len()%3!=0||positions.len()>3_000_000||indices.len()>3_000_000{return Err("invalid/oversize upstream contour buffers".into());}let mut vertices=Vec::new();let mut residual=0.0_f64;for q in positions.chunks_exact(3){let p:[f64;3]=std::array::from_fn(|j|c.bounds[0][j]+q[j] as f64*(c.bounds[1][j]-c.bounds[0][j]));if p.iter().any(|v|!v.is_finite()){return Err("upstream nonfinite vertex".into());}let normal=g.normal(p,c.normal_epsilon)?;residual=residual.max(g.evaluate(p)?.abs());let axis=if normal[0].abs()<0.8{[1.,0.,0.]}else{[0.,1.,0.]};let t=super::vertex_stream::unit([normal[1]*axis[2]-normal[2]*axis[1],normal[2]*axis[0]-normal[0]*axis[2],normal[0]*axis[1]-normal[1]*axis[0]])?;vertices.push(super::primitives::Vertex{position:p.map(|v|v as f32),normal:normal.map(|v|v as f32),uv:[0.,0.],tangent:[t[0] as f32,t[1] as f32,t[2] as f32,1.]});}let stream=Stream{vertices,indices:indices.chunks_exact(3).map(|i|[i[0],i[1],i[2]]).collect()};stream.validate()?;Ok(Contour{stream,resolution:c.resolution,sampled_field_residual_max:residual,topology_verified:false,algorithm:"isosurface DualContouring + MinimiseQEF",uv_tangent_contract:"UV=(0,0), orthonormal arbitrary tangent; no texture parameterization"})}
#[cfg(all(test,feature="surface-contour"))]mod tests{use super::*;use crate::threed::sdf_graph::Field;#[test]fn wrapped_sphere_resolution_residual_and_vertex_abi(){let g=Graph{nodes:vec![Field::Sphere{center:[0.;3],radius:1.}],output:0};let c=Config{bounds:[[-1.5;3],[1.5;3]],resolution:12,normal_epsilon:0.001};let m=polygonize(&g,&c).unwrap();m.stream.validate().unwrap();
assert_eq!(std::mem::size_of::<super::super::primitives::Vertex>(),48);assert!(m.sampled_field_residual_max.is_finite());assert!(!m.topology_verified);} #[test]fn smooth_csg_fixture_counts_finite_and_residual_bounded(){let g=Graph{nodes:vec![Field::Sphere{center:[0.35,0.,0.],radius:0.8},Field::Box{center:[-0.35,0.,0.],half_size:[0.6;3]},Field::SmoothUnion{a:0,b:1,k:0.25}],output:2};let c=Config{bounds:[[-1.6;3],[1.6;3]],resolution:20,normal_epsilon:0.001};let m=polygonize(&g,&c).unwrap();m.stream.validate().unwrap();assert!(m.stream.vertices.len()>=100&&m.stream.indices.len()>=100,"degenerate contour v={} i={}",m.stream.vertices.len(),m.stream.indices.len());assert!(m.stream.vertices.len()<=1_000_000);let cell=(c.bounds[1][0]-c.bounds[0][0])/c.resolution as f64;assert!(m.sampled_field_residual_max.is_finite()&&m.sampled_field_residual_max<2.*cell,"residual {} cell {}",m.sampled_field_residual_max,cell);assert!(m.stream.vertices.iter().all(|v|v.position.iter().chain(v.normal.iter()).all(|x|x.is_finite())));assert!(m.algorithm.contains("DualContouring")&&!m.topology_verified&&m.uv_tangent_contract.contains("no texture"));}}
